    for selected in combinations(options, k):
        ids = tuple(sorted(job["id"] for job in selected))
        if not mandatory.issubset(ids):
            continue

        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        events = []
        for job in selected:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        valid = True
        for _, delta in sorted(events):
            active += delta
            if active > capacity:
                valid = False
                break
        if not valid:
            continue

        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and
                 ((tie == "smallest" and ids < best_ids) or
                  (tie == "largest" and ids > best_ids)))):
            best_value = value
            best_ids = ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


