            if name in closure:
                continue
            closure.add(name)
            row = assigned.get(name)
            if row is None:
                valid = False
                break
            active = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                target = assigned.get(other)
                if target is None or not dep["min"] <= target["version"] <= dep["max"]:
                    valid = False
                    break
                active.append(other)
                pending.append(other)
            edges[name] = active
        if not valid or closure != set(assigned):
            continue

        visiting, finished = set(), set()
        def acyclic(name):
            if name in visiting:
                return False
            if name in finished:
                return True
            visiting.add(name)
            if any(not acyclic(dep) for dep in edges.get(name, [])):
                return False
            visiting.remove(name)
            finished.add(name)
            return True
        if not all(acyclic(name) for name in closure):
            continue

        vector = tuple(assigned[name]["version"] if name in assigned else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_versions = {name: row["version"] for name, row in assigned.items()}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    available = [j for j in jobs if j["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(available, k):
        ids = {j["id"] for j in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active_ends = []
        ok = True
        for job in sorted(subset, key=lambda j: (j["start"], j["end"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                ok = False
                break
        if not ok:
            continue
        value = sum(j["value"] for j in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and selected > best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit_for = {}
    for i, node in enumerate(required):
        bit_for[node] = bit_for.get(node, 0) | (1 << i)
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            next_mask = mask | bit_for.get(edge["v"], 0)
            durations = [(edge["duration"], remaining)]
            if remaining:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, coupons_left in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, coupons_left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], next_mask, coupons_left))
    return {"arrival": None}


