def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best = None
        best_ids = None
        best_value = None

        if mandatory & blocked:
            return {"error": "impossible"}
        options = [job for job in jobs if job["id"] not in blocked]
        for subset in combinations(options, k):
            ids = tuple(sorted(job["id"] for job in subset))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            events = []
            for job in subset:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            feasible = True
            for _, change in sorted(events):
                active += change
                if active > capacity:
                    feasible = False
                    break
            if not feasible:
                continue
            value = sum(job["value"] for job in subset)
            if (best is None or value > best_value or
                (value == best_value and
                 ((tie == "largest" and ids > best_ids) or
                  (tie == "smallest" and ids < best_ids)))):
                best, best_ids, best_value = subset, ids, value
        if best is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


