def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in packages[name]} for name in names}
    choices = [[-1] + sorted(rows[name]) for name in names]
    best_vector = None
    best_versions = None

    for vector in product(*choices):
        assignment = dict(zip(names, vector))
        installed = {name for name, version in assignment.items() if version != -1}
        if any(assignment.get(name, -1) == -1 or
               not bounds[0] <= assignment[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(assignment[name] in blocked.get(name, []) or
               (name in pins and assignment[name] != pins[name])
               for name in installed):
            continue

        reached = set()
        edges = {}
        pending = list(roots)
        valid = True
        while pending and valid:
            name = pending.pop()
            version = assignment.get(name, -1)
            if version == -1 or version not in rows.get(name, {}):
                valid = False
                break
            row = rows[name][version]
            if name in reached:
                continue
            reached.add(name)
            edges[name] = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                other_version = assignment.get(other, -1)
                if (other_version == -1 or
                        not dep["min"] <= other_version <= dep["max"]):
                    valid = False
                    break
                edges[name].append(other)
                pending.append(other)
        if not valid or reached != installed:
            continue

        finished, active = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(acyclic(name) for name in edges):
            continue
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_versions = {name: assignment[name] for name in names
                             if assignment[name] != -1}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _routes(data):
    required = data.get("required", [])
    bits = {node: 0 for node in range(data["n"])}
    for i, node in enumerate(required):
        bits[node] |= 1 << i
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], bits[data["source"]], data["coupons"])
    start_time = data["start"]
    dist = {start_state: start_time}
    queue = [(start_time, *start_state)]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if time != dist.get(state):
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_state = (next_node, mask | bits[next_node], next_remaining)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


