def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=(name_order == "descending"))
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows = {name: {row["version"]: row for row in versions}
                for name, versions in packages.items()}
        choices = [[-1] + sorted(rows[name]) for name in names]
        best_vector = None
        best = None

        for values in product(*choices):
            selected = dict(zip(names, values))
            installed = {name for name, version in selected.items() if version != -1}
            if any(name not in installed or not low <= selected[name] <= high
                   for name, (low, high) in roots.items()):
                continue
            if any(selected[name] not in blocked.get(name, []) for name in ()):
                continue
            if any(selected[name] in blocked.get(name, []) for name in installed):
                continue
            if any(selected[name] != version for name, version in pins.items()
                   if name in installed):
                continue

            edges = {name: [] for name in installed}
            valid = True
            for name in installed:
                row = rows[name][selected[name]]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if other not in installed or not dep["min"] <= selected[other] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != installed:
                continue

            state, cyclic = {}, False
            def visit(name):
                nonlocal cyclic
                if state.get(name) == 1:
                    cyclic = True
                    return
                if state.get(name) == 2 or cyclic:
                    return
                state[name] = 1
                for other in edges[name]:
                    visit(other)
                state[name] = 2
            for name in installed:
                visit(name)
                if cyclic:
                    break
            if cyclic:
                continue

            vector = tuple(selected[name] for name in names)
            if best_vector is None or (vector > best_vector if preference == "maximum"
                                       else vector < best_vector):
                best_vector = vector
                best = {name: selected[name] for name in installed}

        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


