def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [j for j in jobs if j["id"] not in blocked]
    if not mandatory.issubset({j["id"] for j in available}):
        return {"error": "impossible"}
    best_value = None
    best_ids = None
    for subset in _subsets(available, k):
        ids = [j["id"] for j in subset]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        intervals = sorted((j["start"], j["end"]) for j in subset)
        active = []
        feasible = True
        for start, end in intervals:
            active = [finish for finish in active if finish > start]
            active.append(end)
            if len(active) > 2:
                feasible = False
                break
        if not feasible:
            continue
        value = sum(j["value"] for j in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _subsets(items, k):
    # Generate each fixed-size subset without relying on input ordering.
    def rec(start, chosen):
        if len(chosen) == k:
            yield list(chosen)
            return
        need = k - len(chosen)
        for i in range(start, len(items) - need + 1):
            chosen.append(items[i])
            yield from rec(i + 1, chosen)
            chosen.pop()
    yield from rec(0, [])


def _temporal_routes(data):
    import heapq

    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    best = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if time != best.get(state):
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, coupons - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, left)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, left))
    return {"arrival": None}


