from itertools import product


def _dependency_solver(name_order, preference):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=(name_order == "descending"))
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        options = []
        for name in names:
            rows = [row for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            options.append([None] + rows)

        best_vector = None
        best_versions = None
        for choices in product(*options):
            selected = {name: row for name, row in zip(names, choices)
                        if row is not None}
            edges = {name: [] for name in selected}
            valid = True
            for name, bounds in data["roots"].items():
                row = selected.get(name)
                if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue
            for name, row in selected.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = selected.get(dep["name"])
                    if (target is None or
                            not dep["min"] <= target["version"] <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(dep["name"])
                if not valid:
                    break
            if not valid:
                continue

            reached = set()
            stack = list(data["roots"])
            while stack:
                name = stack.pop()
                if name in reached:
                    continue
                reached.add(name)
                stack.extend(edges[name])
            if reached != set(selected):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                for other in edges[name]:
                    if not visit(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in selected):
                continue
            vector = tuple(selected[name]["version"] if name in selected else -1
                           for name in names)
            better = (best_vector is None or
                      (vector < best_vector if preference == "minimum"
                       else vector > best_vector))
            if better:
                best_vector = vector
                best_versions = {name: row["version"]
                                 for name, row in selected.items()}
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (2 * numerator + denominator) // (2 * denominator)
    return numerator // denominator


