import heapq


def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        best = None
        best_vector = None
        names = sorted(packages, reverse=(name_order == "descending"))

        def acyclic(edges):
            done, active = set(), set()

            def visit(node):
                if node in active:
                    return False
                if node in done:
                    return True
                active.add(node)
                if any(not visit(child) for child in edges.get(node, ())):
                    return False
                active.remove(node)
                done.add(node)
                return True

            return all(visit(node) for node in edges)

        def search(chosen, constraints, edges):
            nonlocal best, best_vector
            for name, ranges in constraints.items():
                if name in chosen and any(not (low <= chosen[name] <= high)
                                          for low, high in ranges):
                    return
            todo = [name for name in constraints if name not in chosen]
            if not todo:
                vector = tuple(chosen.get(name, -1) for name in names)
                if best_vector is None or (vector > best_vector if preference == "maximum"
                                           else vector < best_vector):
                    best, best_vector = dict(chosen), vector
                return

            name = min(todo)
            ranges = constraints[name]
            rows = [row for row in packages[name]
                    if all(low <= row["version"] <= high for low, high in ranges)
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            rows.sort(key=lambda row: row["version"], reverse=(preference == "maximum"))
            for row in rows:
                version = row["version"]
                next_chosen = dict(chosen)
                next_chosen[name] = version
                next_constraints = {key: list(value) for key, value in constraints.items()}
                next_edges = {key: list(value) for key, value in edges.items()}
                next_edges.setdefault(name, [])
                valid = True
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    interval = (dep["min"], dep["max"])
                    next_constraints.setdefault(target, []).append(interval)
                    next_edges[name].append(target)
                    if target in next_chosen and not (interval[0] <= next_chosen[target] <= interval[1]):
                        valid = False
                        break
                if valid and acyclic(next_edges):
                    search(next_chosen, next_constraints, next_edges)

        initial = {name: [tuple(bounds)] for name, bounds in roots.items()}
        search({}, initial, {})
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}

    return solve


