def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        features = set(data.get("features", []))

        options = []
        rows_by_name_version = {}
        for name in names:
            versions = []
            for row in packages[name]:
                version = row["version"]
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                versions.append(version)
                rows_by_name_version[name, version] = row
            options.append([-1] + sorted(versions))

        roots = data["roots"]
        for vector in itertools.product(*options):
            selected = dict(zip(names, vector))
            if any(selected.get(name, -1) == -1 or
                   not bounds[0] <= selected[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue

            graph = {}
            valid = True
            for name, version in selected.items():
                if version == -1:
                    continue
                row = rows_by_name_version.get((name, version))
                if row is None:
                    valid = False
                    break
                deps = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    dep_name = dep["name"]
                    dep_version = selected.get(dep_name, -1)
                    if (dep_version == -1 or
                            not dep["min"] <= dep_version <= dep["max"]):
                        valid = False
                        break
                    deps.append(dep_name)
                graph[name] = deps
                if not valid:
                    break
            if not valid:
                continue

            # Only packages reachable through active dependencies of roots belong
            # in the installation; reject disconnected extras.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(graph.get(name, []))
            if any(version != -1 and name not in reachable
                   for name, version in selected.items()):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(dep) for dep in graph.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in reachable):
                continue
            return {"versions": {name: version for name, version in selected.items()
                                 if version != -1}}
        return {"error": "unsatisfiable"}
    return solve


