def _quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        blocked = set(data.get("blocked", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        n = len(jobs)
        for mask in range(1 << n):
            if mask.bit_count() != k:
                continue
            selected = [jobs[i] for i in range(n) if mask >> i & 1]
            ids = {job["id"] for job in selected}
            if ids & blocked or not mandatory <= ids:
                continue
            counts = {}
            for job in selected:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            events = []
            for job in selected:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            feasible = True
            for _, delta in sorted(events):  # end events precede start events at ties
                active += delta
                if active > capacity:
                    feasible = False
                    break
            if not feasible:
                continue
            value = sum(job["value"] for job in selected)
            names = tuple(sorted(ids))
            if (best_value is None or value > best_value or
                (value == best_value and
                 ((tie == "smallest" and names < best_ids) or
                  (tie == "largest" and names > best_ids)))):
                best_value, best_ids = value, names
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


