def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows = {}
        for name in names:
            rows[name] = {row["version"]: row for row in packages[name]}
        choices = []
        for name in names:
            available = [-1]
            for version in rows[name]:
                if version in blocked.get(name, []):
                    continue
                if name in pins and pins[name] != version:
                    continue
                available.append(version)
            choices.append(available)

        best_vector = None
        best_versions = None
        for vector in product(*choices):
            versions = {name: version for name, version in zip(names, vector)
                        if version != -1}
            if any(name not in versions or not low <= versions[name] <= high
                   for name, (low, high) in roots.items()):
                continue
            edges = {name: [] for name in versions}
            valid = True
            for name, version in versions.items():
                for dep in rows[name][version].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if other not in versions or not dep["min"] <= versions[other] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue
            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                if any(not visit(other) for other in edges[name]):
                    return False
                state[name] = 2
                return True
            if any(not visit(name) for name in edges):
                continue
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            if reachable != set(versions):
                continue
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        start = data["start"]
        initial_mask = bit_for.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        distances = {initial: start}
        queue = [(start, source, initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
                for duration, left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_mask = mask | bit_for.get(nxt, 0)
                    next_state = (nxt, next_mask, left)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, next_mask, left))
        return {"arrival": None}
    return solve


