def _resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in packages[name]} for name in names}
    choices = []
    for name in names:
        choices.append([-1] + [v for v in sorted(rows[name])
                               if v not in blocked.get(name, [])
                               and (name not in pins or v == pins[name])])
    best = None

    def check(versions):
        installed = {n for n in names if versions[n] != -1}
        for name, (low, high) in roots.items():
            if name not in installed or not low <= versions[name] <= high:
                return False
        graph = {}
        reached = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reached:
                continue
            if name not in installed:
                return False
            reached.add(name)
            active = []
            for dep in rows[name][versions[name]].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                v = versions[other]
                if v == -1 or not dep["min"] <= v <= dep["max"]:
                    return False
                active.append(other)
                stack.append(other)
            graph[name] = active
        if reached != installed:
            return False
        done, visiting = set(), set()

        def visit(name):
            if name in visiting:
                return False
            if name in done:
                return True
            visiting.add(name)
            if any(not visit(other) for other in graph.get(name, [])):
                return False
            visiting.remove(name)
            done.add(name)
            return True

        return all(visit(name) for name in reached)

    def search(i, versions):
        nonlocal best
        if i == len(names):
            if check(versions):
                vector = tuple(versions[n] for n in names)
                if best is None or vector < best:
                    best = vector
            return
        name = names[i]
        for v in choices[i]:
            versions[name] = v
            search(i + 1, versions)

    search(0, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": {name: v for name, v in zip(names, best) if v != -1}}


