from itertools import product
import heapq
from collections import Counter


def _dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows_by_name = {
        name: {row["version"]: row for row in rows}
        for name, rows in packages.items()
    }
    candidates = []
    for name in names:
        versions = sorted(rows_by_name[name])
        if name in pins:
            versions = [v for v in versions if v == pins[name]]
        versions = [v for v in versions if v not in blocked.get(name, [])]
        candidates.append([-1] + versions)

    best_vector = None
    best = None
    for values in product(*candidates):
        installed = dict(zip(names, values))
        if any(installed.get(name, -1) < 0 or
               not bounds[0] <= installed[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        graph = {}
        valid = True
        for name, version in installed.items():
            if version < 0:
                continue
            row = rows_by_name[name][version]
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = installed.get(target, -1)
                if target_version < 0 or not dep["min"] <= target_version <= dep["max"]:
                    valid = False
                    break
                deps.append(target)
            if not valid:
                break
            graph[name] = deps
        if not valid:
            continue

        # Installed packages must be exactly the active closure of the roots.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph.get(name, []))
        if any(version >= 0 and name not in reachable
               for name, version in installed.items()):
            continue

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in graph.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue
        vector = tuple(installed[name] for name in names)
        if (best_vector is None or
                (vector > best_vector if preference == "maximum"
                 else vector < best_vector)):
            best_vector = vector
            best = {name: version for name, version in installed.items()
                    if version >= 0}
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _build_dependency(preference, name_order):
    return lambda data: _dependency_solver(data, preference, name_order)


def _component_06(data):
    mode = data["rounding"]

    def rounded(numerator, denominator=10000):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    winners = {}
    cutoff = data.get("cutoff", 10**9)
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
