def _quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        if mandatory & blocked:
            return {"error": "impossible"}

        options = [job for job in jobs if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for chosen in combinations(options, k):
            ids = [job["id"] for job in chosen]
            if not mandatory.issubset(ids):
                continue

            counts = {}
            for job in chosen:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active_ends = []
            valid = True
            for job in sorted(chosen, key=lambda row: (row["start"], row["end"], row["id"])):
                active_ends = [end for end in active_ends if end > job["start"]]
                if len(active_ends) >= capacity:
                    valid = False
                    break
                active_ends.append(job["end"])
            if not valid:
                continue

            value = sum(job["value"] for job in chosen)
            sorted_ids = tuple(sorted(ids))
            if (best_value is None or value > best_value or
                    (value == best_value and
                     (sorted_ids < best_ids if tie == "smallest" else sorted_ids > best_ids))):
                best_value = value
                best_ids = sorted_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


