    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows = {}
        for name in names:
            rows[name] = {row["version"]: row for row in packages[name]}

        domains = []
        for name in names:
            versions = sorted(v for v in rows[name]
                              if v not in blocked.get(name, [])
                              and (name not in pins or v == pins[name]))
            domains.append([-1] + versions)

        best = None
        best_vector = None

        def check(values):
            assigned = dict(zip(names, values))
            if any(assigned[name] == -1 or not
                   (bounds[0] <= assigned[name] <= bounds[1])
                   for name, bounds in data["roots"].items()):
                return False

            graph = {}
            reachable = set()
            stack = list(data["roots"])
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                version = assigned[name]
                if version == -1:
                    return False
                row = rows[name][version]
                edges = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    ov = assigned[other]
                    if ov == -1 or not dep["min"] <= ov <= dep["max"]:
                        return False
                    edges.append(other)
                    stack.append(other)
                graph[name] = edges
            if any(assigned[name] != -1 for name in names
                   if name not in reachable):
                return False

            done, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for other in graph.get(name, []):
                    if not visit(other):
                        return False
                active.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in reachable)

        def search(i, values):
            nonlocal best, best_vector
            if i == len(names):
                vector = tuple(values)
                if (best_vector is None or vector < best_vector) and check(values):
                    best_vector = vector
                    best = {name: value for name, value in zip(names, values)
                            if value != -1}
                return
            for version in domains[i]:
                search(i + 1, values + [version])

        search(0, [])
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}
    return solve


