def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        if len(mandatory) > k or mandatory & blocked:
            return {"error": "impossible"}
        best_value = None
        best_ids = None
        n = len(jobs)
        for mask in range(1 << n):
            if mask.bit_count() != k:
                continue
            selected = [jobs[i] for i in range(n) if mask >> i & 1]
            ids = [job["id"] for job in selected]
            idset = set(ids)
            if idset & blocked or not mandatory <= idset:
                continue
            counts = {}
            for job in selected:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            valid = True
            for job in selected:
                overlapping = sum(other["start"] <= job["start"] < other["end"]
                                  for other in selected)
                if overlapping > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in selected)
            ids.sort()
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == "smallest" and ids < best_ids) or
                      (tie == "largest" and ids > best_ids)))):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


