def _resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    rows_by_name = {name: packages[name] for name in names}
    features = set(data.get("features", []))
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        versions = [row["version"] for row in rows_by_name[name]]
        choices.append([None] + versions)
    best_vector = None
    best = None
    for values in product(*choices):
        selected = {name: version for name, version in zip(names, values)
                    if version is not None}
        ok = True
        for name, bounds in roots.items():
            version = selected.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                ok = False
                break
        if not ok:
            continue
        for name, version in selected.items():
            if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                ok = False
                break
        if not ok:
            continue
        reached = set()
        edges = {}
        pending = list(roots)
        while pending and ok:
            name = pending.pop()
            if name in reached:
                continue
            reached.add(name)
            version = selected.get(name)
            if version is None:
                ok = False
                break
            row = next((r for r in rows_by_name[name] if r["version"] == version), None)
            if row is None:
                ok = False
                break
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                dep_version = selected.get(target)
                if dep_version is None or not dep["min"] <= dep_version <= dep["max"]:
                    ok = False
                    break
                deps.append(target)
                pending.append(target)
            edges[name] = deps
        if not ok or reached != set(selected):
            continue
        active, finished = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for dep in edges.get(name, []):
                if not visit(dep):
                    return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in reached):
            continue
        vector = tuple(selected.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector, best = vector, selected
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit_for.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start_state = (data["source"], initial_mask, data["coupons"])
    start_time = data["start"]
    distances = {start_state: start_time}
    queue = [(start_time, data["source"], initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                dest = edge["v"]
                next_mask = mask | bit_for.get(dest, 0)
                next_state = (dest, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, dest, next_mask, next_remaining))
    return {"arrival": None}


