def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows_by_version = {name: {row["version"]: row for row in rows}
                       for name, rows in packages.items()}
    choices = []
    for name in names:
        versions = [version for version in rows_by_version[name]
                    if version not in blocked.get(name, [])
                    and (name not in pins or version == pins[name])]
        choices.append([-1] + sorted(versions))

    best_vector = None
    best_installation = None
    for vector in product(*choices):
        installed = {name: version for name, version in zip(names, vector)
                     if version != -1}
        if any(name not in installed or not low <= installed[name] <= high
               for name, (low, high) in roots.items()):
            continue

        edges = {name: [] for name in installed}
        reachable = set()
        valid = True
        pending = list(roots)
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            if name not in installed:
                valid = False
                break
            reachable.add(name)
            row = rows_by_version[name][installed[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in installed
                        or not dep["min"] <= installed[target] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
                pending.append(target)
        if not valid or reachable != set(installed):
            continue

        finished = set()
        active = set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in installed):
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_installation = installed

    if best_installation is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


