        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        choices = []
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])]
            choices.append([-1] + versions)

        best_vector = None
        best_versions = None
        for values in product(*choices):
            selected = {name: version for name, version in zip(names, values) if version != -1}
            if any(name not in selected or not low <= selected[name] <= high
                   for name, (low, high) in roots.items()):
                continue
            if any(name in selected and selected[name] != version
                   for name, version in pins.items()):
                continue

            graph = {}
            valid = True
            for name, version in selected.items():
                row = next(row for row in packages[name] if row["version"] == version)
                deps = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    dep_name = dep["name"]
                    dep_version = selected.get(dep_name, -1)
                    if dep_version == -1 or not dep["min"] <= dep_version <= dep["max"]:
                        valid = False
                        break
                    deps.append(dep_name)
                graph[name] = deps
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            active = set()
            finished = set()
            cyclic = False

            def visit(name):
                nonlocal cyclic
                reachable.add(name)
                if name in active:
                    cyclic = True
                    return
                if name in finished:
                    return
                active.add(name)
                for other in graph.get(name, []):
                    visit(other)
                active.remove(name)
                finished.add(name)

            for name in roots:
                visit(name)
            if cyclic or reachable != set(selected):
                continue
            vector = tuple(values)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_versions = selected

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


