    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]

        choices = []
        for name in names:
            rows = packages[name]
            choices.append([None] + [row for row in rows
                                     if row["version"] not in blocked.get(name, [])
                                     and (name not in pins or row["version"] == pins[name])])

        best_vector = None
        best_versions = None
        for assignment in product(*choices):
            installed = {name: row for name, row in zip(names, assignment)
                         if row is not None}
            if any(name not in installed or
                   not low <= installed[name]["version"] <= high
                   for name, (low, high) in roots.items()):
                continue

            edges = {name: [] for name in installed}
            valid = True
            for name, row in installed.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if other not in installed or not dep["min"] <= installed[other]["version"] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            reached = set()
            active = set()
            finished = set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                reached.add(name)
                for other in edges[name]:
                    if not visit(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            for root in roots:
                if not visit(root):
                    valid = False
                    break
            if not valid or reached != set(installed):
                continue

            vector = tuple(installed[name]["version"] if name in installed else -1
                           for name in sorted(names, reverse=True))
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: row["version"] for name, row in installed.items()}

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


