def _build_resolver():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows_by_name = {}
        for name in names:
            rows_by_name[name] = {row["version"]: row for row in packages[name]}

        choices = []
        for name in names:
            choices.append([-1] + sorted(rows_by_name[name]))

        best_vector = None
        best_versions = None
        for vector in __import__("itertools").product(*choices):
            installed = {name: version for name, version in zip(names, vector) if version != -1}
            valid = True
            for name, bounds in roots.items():
                version = installed.get(name)
                if version is None or not bounds[0] <= version <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue
            for name, version in installed.items():
                if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                    valid = False
                    break
            if not valid:
                continue

            graph = {name: [] for name in installed}
            for name, version in installed.items():
                row = rows_by_name[name][version]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_version = installed.get(other)
                    if other_version is None or not dep["min"] <= other_version <= dep["max"]:
                        valid = False
                        break
                    graph[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            active, finished = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in graph[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(visit(name) for name in graph):
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(graph[name])
            if reachable != set(installed):
                continue
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_versions = installed

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_jobs():
    def solve(data):
        jobs = [job for job in data["jobs"]
