def _dependencies(data):
    packages = data['packages']
    names = sorted(packages)
    features = set(data.get('features', []))
    roots = data['roots']
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    options = {}
    rowmaps = {}
    for name in names:
        rows = {row['version']: row for row in packages[name]}
        rowmaps[name] = rows
        options[name] = [v for v in rows
                         if v not in blocked.get(name, []) and
                         (name not in pins or pins[name] == v)]

    best_vector = None
    best = None
    for assignment in product(*[[None] + options[name] for name in names]):
        chosen = dict(zip(names, assignment))
        valid = True
        edges = {name: [] for name in names if chosen[name] is not None}
        for name, bounds in roots.items():
            version = chosen.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        for name, version in chosen.items():
            if version is None:
                continue
            for dep in rowmaps[name][version].get('deps', []):
                feature = dep.get('feature', '')
                if feature and feature not in features:
                    continue
                target = dep['name']
                target_version = chosen.get(target)
                if (target_version is None or
                        not dep['min'] <= target_version <= dep['max']):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in edges):
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if any(version is not None and name not in reachable
               for name, version in chosen.items()):
            continue

        vector = tuple(chosen[name] if chosen[name] is not None else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = {name: version for name, version in chosen.items()
                    if version is not None}
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}


def _jobs(data):
    jobs = [job for job in data['jobs']
