def _quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best = None
        best_ids = None

        for mask in range(1 << len(jobs)):
            if mask.bit_count() != k:
                continue
            chosen = [jobs[i] for i in range(len(jobs)) if mask >> i & 1]
            ids = {job["id"] for job in chosen}
            if ids & blocked or not mandatory.issubset(ids):
                continue

            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            feasible = True
            for job in chosen:
                overlap = sum(other["start"] <= job["start"] < other["end"]
                              for other in chosen)
                if overlap > capacity:
                    feasible = False
                    break
            if not feasible:
                continue

            selected = sorted(ids)
            value = sum(job["value"] for job in chosen)
            if (best is None or value > best or
                    (value == best and
                     (selected < best_ids if tie == "smallest" else selected > best_ids))):
                best, best_ids = value, selected

        if best is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best}
    return solve


