from collections import Counter
from itertools import product, combinations
import heapq


def _build_interval(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for selected in combinations((j for j in jobs if j["id"] not in blocked), k):
            ids = tuple(sorted(j["id"] for j in selected))
            if not mandatory.issubset(ids):
                continue
            counts = Counter(j["group"] for j in selected)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ends = []
            valid = True
            for job in sorted(selected, key=lambda j: (j["start"], j["end"], j["id"])):
                while ends and ends[0] <= job["start"]:
                    heapq.heappop(ends)
                heapq.heappush(ends, job["end"])
                if len(ends) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(j["value"] for j in selected)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     (ids > best_ids if tie == "largest" else ids < best_ids))):
                best_value, best_ids = value, ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_ledger():
    def rounded(n, mode):
        if mode == "half_up":
            return (n + 5000) // 10000
        return n // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            tax = rounded(raw * event.get("tax_bp", 0), mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_dependencies():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]

        choices = []
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])
                        and (name not in pins or row["version"] == pins[name])]
            choices.append([None] + versions)

        feasible = []
        for assignment in product(*choices):
            selected = {name: version for name, version in zip(names, assignment)
                        if version is not None}
            if any(name not in selected or not low <= selected[name] <= high
                   for name, (low, high) in roots.items()):
                continue

            graph = {name: [] for name in selected}
            okay = True
            for name, version in selected.items():
                row = next(r for r in packages[name] if r["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if other not in selected or not dep["min"] <= selected[other] <= dep["max"]:
                        okay = False
                        break
                    graph[name].append(other)
                if not okay:
                    break
            if not okay:
                continue

            active, done = set(), set()
            def visit(node):
                if node in active:
                    return False
                if node in done:
                    return True
                active.add(node)
                if any(not visit(child) for child in graph[node]):
                    return False
                active.remove(node)
                done.add(node)
                return True
            if not all(visit(name) for name in graph):
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                node = stack.pop()
                if node in reachable:
                    continue
                reachable.add(node)
                stack.extend(graph[node])
            if reachable != set(selected):
                continue
            vector = tuple(selected.get(name, -1) for name in names)
            feasible.append((vector, selected))

        if not feasible:
            return {"error": "unsatisfiable"}
        return {"versions": min(feasible, key=lambda item: item[0])[1]}
    return solve


def _build_routes():
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = bit.get(source, 0)
        start = (source, initial_mask, data["coupons"])
        distances = {start: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]
        while queue:
            arrival, node, mask, coupons = heapq.heappop(queue)
            state = (node, mask, coupons)
            if arrival != distances.get(state):
                continue
            if node == data["target"] and mask == full:
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], coupons)]
                if coupons:
                    options.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons - 1))
                for duration, remaining in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_mask = mask | bit.get(nxt, 0)
                    next_state = (nxt, next_mask, remaining)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, nxt, next_mask, remaining))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_interval(1, "largest"),
    "component_02": _build_interval(2, "largest"),
    "component_03": _build_interval(1, "smallest"),
    "component_04": _build_interval(2, "smallest"),
    "component_05": _build_interval(1, "largest"),
    "component_06": _build_ledger(),
    "component_07": _build_dependencies(),
    "component_08": _build_routes(),
}

