def _ledger(data, sequence_first, original_tax):
    mode = data.get("rounding", "floor")

    def rounded(n, d=10000):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
