def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = list(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        options = []
        for name in names:
            versions = []
            for row in packages[name]:
                version = row["version"]
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                versions.append(version)
            options.append([None] + versions)

        best_vector = None
        best_install = None
        order = sorted(names, reverse=True)
        for choice in product(*options):
            install = {name: version for name, version in zip(names, choice)
                       if version is not None}
            valid = True
            for name, bounds in roots.items():
                if name not in install or not bounds[0] <= install[name] <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue

            edges = {name: [] for name in install}
            for name, version in install.items():
                row = next(r for r in packages[name] if r["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    if target not in install or not dep["min"] <= install[target] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(install):
                continue

            active, finished = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in install):
                continue
            vector = tuple(install.get(name, -1) for name in order)
            if best_vector is None or vector < best_vector:
                best_vector, best_install = vector, install

        if best_install is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_install}
    return solve


