def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        n = len(jobs)
        for mask in range(1 << n):
            if mask.bit_count() != k:
                continue
            chosen = [jobs[i] for i in range(n) if mask >> i & 1]
            ids = {j["id"] for j in chosen}
            if ids & blocked or not mandatory <= ids:
                continue
            counts = {}
            for job in chosen:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(chosen, key=lambda j: (j["start"], j["end"]))
            ends = []
            valid = True
            for job in ordered:
                ends = [end for end in ends if end > job["start"]]
                ends.append(job["end"])
                if len(ends) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            names = sorted(ids)
            value = sum(j["value"] for j in chosen)
            if (best_value is None or value > best_value or
                (value == best_value and
                 (names < best_ids if tie == "smallest" else names > best_ids))):
                best_value, best_ids = value, names
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _ledger(data):
