def _resolver(data):
    from itertools import product

    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in packages[name]} for name in names}
    choices = []
    for name in names:
        versions = sorted(v for v in rows[name]
                          if v not in blocked.get(name, [])
                          and (name not in pins or pins[name] == v))
        choices.append([-1] + versions)

    best = None
    best_versions = None
    for values in product(*choices):
        installed = {name: v for name, v in zip(names, values) if v != -1}
        if any(name not in installed or not bounds[0] <= installed[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        active, finished = set(), set()
        valid = True

        def visit(name):
            nonlocal valid
            if name in active:
                valid = False
                return
            if name in finished or not valid:
                return
            if name not in installed:
                valid = False
                return
            active.add(name)
            row = rows[name][installed[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                version = installed.get(other)
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                visit(other)
                if not valid:
                    break
            active.remove(name)
            finished.add(name)

        for name, bounds in roots.items():
            if name in installed and not bounds[0] <= installed[name] <= bounds[1]:
                valid = False
                break
            visit(name)
            if not valid:
                break
        if not valid or finished != set(installed):
            continue
        if best is None or values < best:
            best = values
            best_versions = installed
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _jobs(data):
    from itertools import combinations

