def _build_component_06():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        rows = {}
        for name in names:
            rows[name] = {r["version"]: r for r in packages[name]}
        # Enumerate vectors in required lexicographically descending order.
        choices = []
        for name in names:
            versions = sorted(rows[name], reverse=True)
            choices.append(versions + [-1])

        for vector in product(*choices):
            assigned = dict(zip(names, vector))
            edges = {}
            valid = True
            for name, bounds in roots.items():
                v = assigned[name]
                if v < bounds[0] or v > bounds[1]:
                    valid = False
                    break
            if not valid:
                continue
            for name, version in assigned.items():
                if version == -1:
                    continue
                if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                    valid = False
                    break
                deps = []
                for dep in rows[name][version].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    target_version = assigned[target]
                    if not dep["min"] <= target_version <= dep["max"]:
                        valid = False
                        break
                    deps.append(target)
                edges[name] = deps
                if not valid:
                    break
            if not valid:
                continue
            # Installed packages must be exactly the closure of roots.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                if assigned[name] == -1:
                    valid = False
                    break
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if not valid or any((v != -1) != (name in reachable)
                                for name, v in assigned.items()):
                continue
            active, done = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                done.add(name)
                return True

            if not all(visit(name) for name in reachable):
                continue
            return {"versions": {name: assigned[name] for name in names
                                 if assigned[name] != -1}}
        return {"error": "unsatisfiable"}
    return solve


