def _component_06(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = [[None] + list(packages[name]) for name in names]
    best_vector = None
    best_versions = None

    for assignment in product(*choices):
        selected = {name: row for name, row in zip(names, assignment)
                    if row is not None}
        valid = True
        for name, bounds in roots.items():
            row = selected.get(name)
            if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        edges = {name: [] for name in selected}
        for name, row in selected.items():
            version = row["version"]
            if version in blocked.get(name, []):
                valid = False
                break
            if name in pins and version != pins[name]:
                valid = False
                break
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_row = selected.get(target)
                if (target_row is None or
                        not dep["min"] <= target_row["version"] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        pending = list(roots)
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            if name not in selected:
                valid = False
                break
            reachable.add(name)
            pending.extend(edges[name])
        if not valid or reachable != set(selected):
            continue

        state = {}

        def acyclic(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for target in edges[name]:
                if not acyclic(target):
                    return False
            state[name] = 2
            return True

        if not all(acyclic(name) for name in selected):
            continue

        vector = tuple(selected[name]["version"] if name in selected else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_versions = {name: row["version"]
                             for name, row in selected.items()}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        if any(sum(job["start"] <= time < job["end"] for job in subset) > 2
               for time in (job["start"] for job in subset)):
            continue

        value = sum(job["value"] for job in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bits = {node: 1 << index for index, node in enumerate(required)}
    full_mask = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bits.get(source, 0)
    initial_state = (source, initial_mask, data["coupons"])
    start = data["start"]
    distances = {initial_state: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full_mask:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [edge["duration"]]
            if remaining:
                durations.append(max(2, edge["duration"] - edge.get("discount", 0)))
            for index, duration in enumerate(durations):
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_remaining = remaining - (1 if index == 1 else 0)
                destination = edge["v"]
                next_mask = mask | bits.get(destination, 0)
                next_state = (destination, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, destination, next_mask,
                                           next_remaining))
    return {"arrival": None}


