        return {"balances": balances}

    return solve


def _build_resolver():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        initial_constraints = {name: [tuple(bounds)]
                               for name, bounds in data["roots"].items()}
        best_vector = None
        best = None

        def visit(constraints, chosen, edges):
            nonlocal best_vector, best
            for name, version in chosen.items():
                if any(not low <= version <= high
                       for low, high in constraints.get(name, [])):
                    return
            unresolved = sorted(set(constraints) - set(chosen))
            if not unresolved:
                finished, active = set(), set()

                def acyclic(name):
                    if name in active:
                        return False
                    if name in finished:
                        return True
                    active.add(name)
                    if any(not acyclic(other) for other in edges.get(name, ())):
                        return False
                    active.remove(name)
                    finished.add(name)
                    return True

                if not all(acyclic(name) for name in edges):
                    return
                vector = tuple(chosen.get(name, -1) for name in names)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best = dict(chosen)
                return

            name = unresolved[0]
            ranges = constraints[name]
            rows = sorted(packages.get(name, []),
                          key=lambda row: row["version"], reverse=True)
            for row in rows:
                version = row["version"]
                if any(not low <= version <= high for low, high in ranges):
                    continue
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                next_constraints = {key: list(value)
                                    for key, value in constraints.items()}
                next_chosen = dict(chosen)
                next_chosen[name] = version
                next_edges = {key: set(value) for key, value in edges.items()}
                next_edges.setdefault(name, set())
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    next_constraints.setdefault(target, []).append(
                        (dep["min"], dep["max"]))
                    next_edges[name].add(target)
                visit(next_constraints, next_chosen, next_edges)

        visit(initial_constraints, {}, {})
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}

    return solve


def _build_jobs():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for subset in combinations(jobs, k):
            ids = [job["id"] for job in subset]
            if blocked.intersection(ids) or not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            active = []
            feasible = True
            for job in ordered:
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > 2:
                    feasible = False
                    break
            if not feasible:
                continue

            selected = sorted(ids)
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and selected > best_ids)):
                best_value = value
                best_ids = selected

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}

    return solve


SOLVERS = {
    "component_01": _build_route("exact", 1),
    "component_02": _build_route("at_most", 2),
    "component_03": _build_route("exact", 2),
    "component_04": _build_route("at_most", 1),
    "component_05": _build_route("exact", 1),
    "component_06": _build_ledger(),
    "component_07": _build_resolver(),
    "component_08": _build_jobs(),
}

