import heapq
import itertools
from collections import Counter


def _route(data, exact, minimum_duration):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    visit = {node: 0 for node in range(data["n"])}
    for i, node in enumerate(required):
        visit[node] = visit.get(node, 0) | (1 << i)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source, target = data["source"], data["target"]
    coupons = data["coupons"]
    initial = (source, visit.get(source, 0), 0)
    dist = {initial: data["start"]}
    queue = [(data["start"],) + initial]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if dist.get(state) != time:
            continue
        if node == target and mask == full and (not exact or used == coupons):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | visit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        tax = rounded(net * event.get("tax_bp", 0), mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    choices = {}
    for name in names:
        rows = [row for row in packages[name]
                if row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        choices[name] = [None] + rows

    best_vector = None
    best = None
    for selection in itertools.product(*(choices[name] for name in names)):
        installed = {name: row for name, row in zip(names, selection)
                     if row is not None}
        graph = {name: [] for name in installed}
        valid = True
        for name, bounds in data["roots"].items():
            row = installed.get(name)
            if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        for name, row in installed.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = installed.get(dep["name"])
                if other is None or not dep["min"] <= other["version"] <= dep["max"]:
                    valid = False
                    break
                graph[name].append(dep["name"])
            if not valid:
                break
        if not valid:
            continue

        reached, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in reached:
                return True
            active.add(name)
            for other in graph[name]:
                if not visit(other):
                    return False
            active.remove(name)
            reached.add(name)
            return True

        if not all(visit(name) for name in data["roots"]):
            continue
        if reached != set(installed):
            continue
        vector = tuple(installed[name]["version"] if name in installed else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = {name: installed[name]["version"] for name in names
                    if name in installed}
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _intervals(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset({job["id"] for job in jobs}):
        return {"error": "impossible"}
    k = data["k"]
    if k > len(jobs):
        return {"error": "impossible"}

    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for selected in itertools.combinations(jobs, k):
        ids = {job["id"] for job in selected}
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in selected)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in selected:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        if any((active := active + delta) > 2
               for _, delta in sorted(events)):
            continue
        value = sum(job["value"] for job in selected)
        chosen_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and chosen_ids > best_ids)):
            best_value, best_ids = value, chosen_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


