        for chosen in combinations(jobs, k):
            ids = tuple(sorted(job["id"] for job in chosen))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in chosen:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            points = []
            for job in chosen:
                points.append((job["start"], 1))
                points.append((job["end"], -1))
            active = 0
            feasible = True
            for _, delta in sorted(points):
                active += delta
                if active > capacity:
                    feasible = False
                    break
            if not feasible:
                continue

            value = sum(job["value"] for job in chosen)
            if (best_ids is None or value > best_value or
                    (value == best_value and
                     (ids > best_ids if tie == "largest" else ids < best_ids))):
                best_ids, best_value = ids, value

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


