import heapq
from itertools import product


def _route_solver(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    start_mask = bit.get(source, 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    # State includes both required visits and coupons already spent.
    initial = (source, start_mask, 0)
    best = {initial: data["start"]}
    queue = [(data["start"], source, start_mask, 0)]
    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full and
                (coupon_rule == "at_most" or used == data["coupons"])):
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < best.get(next_state, float("inf")):
                    best[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node,
                                           next_mask, next_used))
    return {"arrival": None}


def _route_factory(coupon_rule, minimum_duration):
    return lambda data: _route_solver(data, coupon_rule, minimum_duration)


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(numerator):
        if half_up:
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    candidates = {}
    for name in names:
        rows = []
        for row in packages[name]:
            version = row["version"]
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            rows.append(row)
        candidates[name] = rows

    choices = [[None] + candidates[name] for name in names]
    best_vector = None
    best_install = None
    roots = data["roots"]

    for assignment in product(*choices):
        selected = {name: row for name, row in zip(names, assignment)
                    if row is not None}
        valid = True
        for name, bounds in roots.items():
            row = selected.get(name)
            if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        edges = {name: [] for name in selected}
        reached = set()
        pending = list(roots)
        while pending and valid:
            name = pending.pop()
            if name in reached:
                continue
            row = selected.get(name)
            if row is None:
                valid = False
                break
            reached.add(name)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                dep_name = dep["name"]
                dep_row = selected.get(dep_name)
                if (dep_row is None or
                        not dep["min"] <= dep_row["version"] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(dep_name)
                pending.append(dep_name)
        if not valid or reached != set(selected):
            continue

        # Reject cycles in the active dependency graph.
        state = {}

        def acyclic(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for other in edges[name]:
                if not acyclic(other):
                    return False
            state[name] = 2
            return True

        if not all(acyclic(name) for name in selected):
            continue
        vector = tuple(selected[name]["version"] if name in selected else -1
                       for name in names)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_install = {name: selected[name]["version"]
                            for name in names if name in selected}

    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in __import__("itertools").combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        valid = True
        for group, bounds in quotas.items():
            count = counts.get(group, 0)
            if not bounds[0] <= count <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        value = sum(job["value"] for job in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value = value
            best_ids = sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


