def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        rows = sorted(packages[name], key=lambda row: row["version"])
        choices.append([None] + rows)

    best_key = None
    best_versions = None
    for assignment in product(*choices):
        selected = {name: row for name, row in zip(names, assignment)
                    if row is not None}
        versions = {name: row["version"] for name, row in selected.items()}
        if any(name not in versions or
               not bounds[0] <= versions[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(name in versions and versions[name] in blocked.get(name, [])
               for name in names):
            continue
        if any(name in versions and versions[name] != version
               for name, version in pins.items()):
            continue

        edges = {name: [] for name in selected}
        valid = True
        for name, row in selected.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in versions or
                        not dep["min"] <= versions[target] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        closure = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in closure:
                continue
            if name not in selected:
                valid = False
                break
            closure.add(name)
            stack.extend(edges[name])
        if not valid or closure != set(selected):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in selected):
            continue

        key = tuple(versions.get(name, -1) for name in names)
        if best_key is None or key < best_key:
            best_key = key
            best_versions = versions

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _jobs(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None

    available = [job for job in jobs if job["id"] not in blocked]
    for subset in product((False, True), repeat=len(available)):
        chosen = [job for job, take in zip(available, subset) if take]
        if len(chosen) != k:
            continue
        ids = sorted(job["id"] for job in chosen)
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


