from itertools import product, combinations


def _dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    choices = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        choices.append([-1] + versions)

    order = names if name_order == "ascending" else list(reversed(names))
    best_key = None
    best = None

    for values in product(*choices):
        selected = dict(zip(names, values))
        if any(selected.get(name, -1) < bounds[0]
               or selected.get(name, -1) > bounds[1]
               for name, bounds in roots.items()):
            continue

        rows = {}
        valid = True
        for name, version in selected.items():
            if version == -1:
                continue
            row = next(row for row in packages[name]
                       if row["version"] == version)
            rows[name] = row

        edges = {name: [] for name in rows}
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = selected[target]
                if version < dep["min"] or version > dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if reachable != set(rows):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(child) for child in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in rows):
            continue

        key = tuple(selected[name] for name in order)
        if best_key is None or (key < best_key if preference == "minimum" else key > best_key):
            best_key = key
            best = {name: version for name, version in selected.items() if version != -1}

    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _dep_builder(preference, order):
    return lambda data: _dependency_solver(data, preference, order)


def _component_06(data):
    mode = data["rounding"]
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))

    def rounded(num, den):
        if mode == "half_up":
            return (num + den // 2) // den
        return num // den

    for _, event in winners.values():
