import heapq
import itertools


def _temporal(data, minimum_duration, exact):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit.get(source, 0)
    start = data["start"]
    budget = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    initial = (source, initial_mask, 0)
    distances = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if (node == data["target"] and mask == full
                and (not exact or used == budget)):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(depart + edge["duration"], used)]
            if used < budget:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((depart + duration, used + 1))
            next_mask = mask | bit.get(edge["v"], 0)
            for arrival, next_used in options:
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], next_mask, next_used))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(numerator, denominator=10000):
        if half_up:
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        versions = sorted(v for v in rows[name]
                          if v not in blocked.get(name, []))
        choices.append([-1] + versions)

    best_vector = None
    best_install = None
    for vector in itertools.product(*choices):
        installed = {name: version for name, version in zip(names, vector)
                     if version != -1}
        if any(name not in installed or not bounds[0] <= installed[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(name in installed and installed[name] != version
               for name, version in pins.items()):
            continue

        graph = {name: [] for name in installed}
        valid = True
        for name, version in installed.items():
            row = rows[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in installed or
                        not dep["min"] <= installed[target] <= dep["max"]):
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set(roots)
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name not in installed:
                valid = False
                break
            for target in graph[name]:
                if target not in reachable:
                    reachable.add(target)
                    pending.append(target)
        if not valid or reachable != set(installed):
            continue

        colors = {}
        def acyclic(name):
            color = colors.get(name, 0)
            if color == 1:
                return False
            if color == 2:
                return True
            colors[name] = 1
            if any(not acyclic(target) for target in graph[name]):
                return False
            colors[name] = 2
            return True

        if any(not acyclic(name) for name in graph):
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_install = installed

    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _jobs(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    if k > len(jobs):
        return {"error": "impossible"}
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for selected in itertools.combinations(jobs, k):
        ids = sorted(job["id"] for job in selected)
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active = []
        feasible = True
        for job in sorted(selected, key=lambda item: (item["start"], item["end"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                feasible = False
                break
        if not feasible:
            continue

        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


