from itertools import product, combinations
import heapq


def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=(name_order == "descending"))
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        options = {}
        rows_by_version = {}
        for name in names:
            versions = []
            for row in packages[name]:
                version = row["version"]
                rows_by_version[(name, version)] = row
                if version not in blocked.get(name, []) and (name not in pins or pins[name] == version):
                    versions.append(version)
            options[name] = [None] + sorted(versions)

        best = None
        best_vector = None
        for values in product(*(options[name] for name in names)):
            chosen = {name: version for name, version in zip(names, values)
                      if version is not None}
            if any(name not in chosen or not low <= chosen[name] <= high
                   for name, (low, high) in data["roots"].items()):
                continue

            edges = {name: [] for name in chosen}
            valid = True
            for name, version in chosen.items():
                for dep in rows_by_version[(name, version)].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    if target not in chosen or not dep["min"] <= chosen[target] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set(data["roots"])
            stack = list(reachable)
            while stack:
                node = stack.pop()
                if node not in chosen:
                    valid = False
                    break
                for target in edges[node]:
                    if target not in reachable:
                        reachable.add(target)
                        stack.append(target)
            if not valid or reachable != set(chosen):
                continue

            visiting, finished = set(), set()

            def acyclic(node):
                if node in visiting:
                    return False
                if node in finished:
                    return True
                visiting.add(node)
                for target in edges[node]:
                    if not acyclic(target):
                        return False
                visiting.remove(node)
                finished.add(node)
                return True

            if not all(acyclic(node) for node in chosen):
                continue
            vector = tuple(chosen.get(name, -1) for name in names)
            if best is None or (vector > best_vector if preference == "maximum"
                                else vector < best_vector):
                best, best_vector = chosen, vector
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))

    def rounded(numerator):
        if data["rounding"] == "floor":
            return numerator // 10000
        return (numerator + 5000) // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _quota_intervals(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        starts = {job["start"] for job in subset}
        if any(sum(job["start"] <= time < job["end"] for job in subset) > 2
               for time in starts):
            continue
        value = sum(job["value"] for job in subset)
        if (best_ids is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_ids, best_value = ids, value

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _routes(data):
    required = data.get("required", [])
    indexes = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = 1 << indexes[source] if source in indexes else 0
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (source, initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, remaining - 1))
            for duration, next_remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | (1 << indexes[next_node] if next_node in indexes else 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


