            continue
        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in graph.get(name, [])):
                return False
            state[name] = 2
            return True
        if any(not visit(name) for name in reachable):
