def combinations(items, count):
    # Small bounded subset enumeration, without relying on a third-party module.
    if count == 0:
        yield ()
        return
    def visit(start, chosen):
        if len(chosen) == count:
            yield tuple(chosen)
            return
        needed = count - len(chosen)
        for index in range(start, len(items) - needed + 1):
            yield from visit(index + 1, chosen + [items[index]])
    yield from visit(0, [])


