        stack = list(constraints)
        valid = True
        while stack and valid:
            name = stack.pop()
            row = installed.get(name)
            if row is None:
                valid = False
                break
            ver = row["version"]
            if any(not lo <= ver <= hi for lo, hi in constraints.get(name, [])):
                valid = False
                break
            if name in reached:
                continue
            reached.add(name)
            edges[name] = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                lo, hi = dep["min"], dep["max"]
                constraints.setdefault(other, []).append((lo, hi))
