                if row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + rows)

    best_vector = None
    best_versions = None
    for selection in product(*choices):
        installed = {name: row for name, row in zip(names, selection)
                     if row is not None}
        stack = []
        valid = True
        for name, bounds in data["roots"].items():
            row = installed.get(name)
            if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                valid = False
                break
            stack.append(name)
        if not valid:
            continue

        reached = set()
        edges = {}
        while stack and valid:
            name = stack.pop()
            if name in reached:
                continue
            reached.add(name)
            edges[name] = []
            row = installed[name]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                target = installed.get(other)
                if (target is None or
                        not dep["min"] <= target["version"] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(other)
                if other not in reached:
                    stack.append(other)
        if not valid or reached != set(installed):
            continue

        active, finished = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
