            row = next(row for row in packages[name] if row["version"] == version)
            active = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = selected.get(dep["name"])
                if target is None or not dep["min"] <= target <= dep["max"]:
                    valid = False
                    break
                active.append(dep["name"])
            edges[name] = active
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(selected):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in reachable):
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = selected

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _jobs(data):
