from itertools import product, combinations
import heapq


def _make_ledger(priority, discounted_tax):
    def rounded(n, d, mode):
        return (n + d // 2) // d if mode == "half_up" else n // d

    def solve(data):
        chosen = {}
        cutoff = data.get("cutoff", 10**9)
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            if priority == "sequence_first":
                rank = (seq, event.get("revision", 0), pos)
            else:
                rank = (event.get("revision", 0), pos)
            if event_id not in chosen or rank > chosen[event_id][0]:
                chosen[event_id] = (rank, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            base = net if discounted_tax else raw
            tax = rounded(base * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependency_solver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    options = [[None] + list(packages[name]) for name in names]
    best_key = None
    best_versions = None

    for choices in product(*options):
        installed = {name: row for name, row in zip(names, choices) if row is not None}
        versions = {name: row["version"] for name, row in installed.items()}
        if any(name not in installed or not bounds[0] <= versions[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(name in installed and
               (versions[name] in blocked.get(name, []) or
                (name in pins and versions[name] != pins[name]))
               for name in names):
            continue

        edges = {}
        valid = True
        for name, row in installed.items():
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                dep_name = dep["name"]
                deps.append(dep_name)
                if (dep_name not in installed or
                    not dep["min"] <= versions[dep_name] <= dep["max"]):
                    valid = False
                    break
            edges[name] = deps
            if not valid:
                break
        if not valid:
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for other in edges.get(name, []):
                if not visit(other):
                    return False
            state[name] = 2
            return True

        if not all(visit(name) for name in installed):
            continue
        closure = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in closure:
                continue
            closure.add(name)
            stack.extend(edges.get(name, []))
        if closure != set(installed):
            continue

        key = tuple(versions.get(name, -1) for name in sorted(names, reverse=True))
        if best_key is None or key > best_key:
            best_key = key
            best_versions = versions

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _job_solver(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    jobs = [job for job in jobs if job["id"] not in blocked]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for chosen in combinations(jobs, k):
        ids = {job["id"] for job in chosen}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        # At equal times, process interval ends before starts (half-open intervals).
        events = []
        for job in chosen:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        feasible = True
        for _, delta in sorted(events):
            active += delta
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue

        value = sum(job["value"] for job in chosen)
        selected = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and selected > best_ids)):
            best_value, best_ids = value, selected

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _route_solver(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    start = data["start"]
    remaining = data["coupons"]
    initial = (source, initial_mask, remaining)
    distances = {initial: start}
    queue = [(start, source, initial_mask, remaining)]

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, coupons - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                dest = edge["v"]
                next_mask = mask | bit_for.get(dest, 0)
                next_state = (dest, next_mask, left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, dest, next_mask, left))
    return {"arrival": None}


