        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue

        vector = tuple(selected[name]["version"] if name in selected else -1
                       for name in names)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_result = {name: row["version"] for name, row in selected.items()}

    if best_result is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_result}


def _component_07(data):
