        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data.get("roots", {})
        choices = []
        for name in names:
            choices.append([None] + [row for row in packages[name]
                                     if row["version"] not in blocked.get(name, [])
                                     and (name not in pins or row["version"] == pins[name])])

        best_key = None
        best = None
        for selection in product(*choices):
            rows = {name: row for name, row in zip(names, selection) if row is not None}
            if any(name not in rows or not low <= rows[name]["version"] <= high
                   for name, (low, high) in roots.items()):
                continue

            edges = {name: [] for name in rows}
            valid = True
            for name, row in rows.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    edges[name].append(other)
                    if (other not in rows or
                            not dep["min"] <= rows[other]["version"] <= dep["max"]):
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue

            # Installed packages must be exactly the roots' active dependency closure.
            closure = set()
            pending = list(roots)
            while pending:
                name = pending.pop()
                if name in closure:
                    continue
                if name not in rows:
                    valid = False
                    break
                closure.add(name)
                pending.extend(edges[name])
            if not valid or closure != set(rows):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(visit(name) for name in rows):
                continue

            key = tuple(rows[name]["version"] if name in rows else -1
                        for name in reversed(names))
            if best_key is None or key < best_key:
                best_key = key
                best = {name: rows[name]["version"] for name in rows}
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


