def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        features = set(data.get("features", []))

        choices = []
        for name in names:
            rows = sorted(packages[name], key=lambda row: row["version"])
            choices.append([None] + [row for row in rows
                                     if row["version"] not in blocked.get(name, [])
                                     and (name not in pins or row["version"] == pins[name])])

        best_vector = None
        best_versions = None
        for selected in product(*choices):
            installed = {name: row for name, row in zip(names, selected) if row is not None}
            versions = {name: row["version"] for name, row in installed.items()}
            if any(name not in versions or not low <= versions[name] <= high
                   for name, (low, high) in roots.items()):
                continue

            edges = {name: [] for name in installed}
            valid = True
            for name, row in installed.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    if target not in versions or not dep["min"] <= versions[target] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            # Only the dependency closure of roots may be installed.
            closure = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in closure:
                    continue
                closure.add(name)
                stack.extend(edges.get(name, []))
            if closure != set(installed):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(visit(name) for name in edges):
                continue

            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector, best_versions = vector, versions

        if best_vector is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source, target = data["source"], data["target"]
        initial_mask = bit_for.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        distances = {initial: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == target and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(depart + edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((depart + duration, remaining - 1))
                next_mask = mask | bit_for.get(edge["v"], 0)
                for arrival, next_remaining in options:
                    if arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, edge["v"], next_mask, next_remaining))
        return {"arrival": None}
    return solve


