def _temporal_solver(minimum_duration, exact_coupons):
    def solve(data):
        required = data.get("required", [])
        full_mask = (1 << len(required)) - 1
        visited = {data["source"]: 0}
        for index, node in enumerate(required):
            if node == data["source"]:
                visited[data["source"]] |= 1 << index

        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], visited[data["source"]], 0)
        distance = {start_state: data["start"]}
        queue = [(data["start"],) + start_state]
        coupon_limit = data["coupons"]

        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distance.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full_mask and
                    (used == coupon_limit if exact_coupons else used <= coupon_limit)):
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [(edge["duration"], used)]
                if used < coupon_limit:
                    discounted = max(minimum_duration,
                                     edge["duration"] - edge.get("discount", 0))
                    durations.append((discounted, used + 1))
                next_node = edge["v"]
                next_mask = mask | visited.get(next_node, 0)
                for duration, next_used in durations:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, next_used)
                    if next_time < distance.get(next_state, float("inf")):
                        distance[next_state] = next_time
                        heapq.heappush(queue, (next_time,) + next_state)
        return {"arrival": None}

    return solve


