    names = sorted(packages)
    features = set(data.get("features", []))
    constraints = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
    best_vector = None
    best_versions = None

    def is_acyclic(graph):
        done = set()
        active = set()

        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            for other in graph.get(name, ()):
                if not visit(other):
                    return False
            active.remove(name)
            done.add(name)
            return True

        return all(visit(name) for name in graph)

    def search(versions, ranges, graph):
        nonlocal best_vector, best_versions
        for name, version in versions.items():
            if any(not low <= version <= high
                   for low, high in ranges.get(name, ())):
                return

        unresolved = [name for name in ranges if name not in versions]
        if not unresolved:
            if not is_acyclic(graph):
                return
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(versions)
            return

        name = min(unresolved)
        rows = packages.get(name, [])
        blocked = data.get("blocked", {}).get(name, [])
        pin = data.get("pins", {}).get(name)
        for row in rows:
            version = row["version"]
            if version in blocked or (pin is not None and version != pin):
                continue
            if any(not low <= version <= high
                   for low, high in ranges.get(name, ())):
                continue

            next_versions = dict(versions)
            next_versions[name] = version
            next_ranges = {key: list(value) for key, value in ranges.items()}
            dependencies = [dep for dep in row.get("deps", [])
                            if not dep.get("feature") or dep["feature"] in features]
            next_graph = {key: list(value) for key, value in graph.items()}
            next_graph[name] = []
            valid = True
            for dep in dependencies:
                dep_name = dep["name"]
                next_ranges.setdefault(dep_name, []).append((dep["min"], dep["max"]))
                next_graph[name].append(dep_name)
                if dep_name in next_versions and not (
                        dep["min"] <= next_versions[dep_name] <= dep["max"]):
                    valid = False
            if valid:
                search(next_versions, next_ranges, next_graph)

    search({}, constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_08(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
