import heapq
import itertools
from collections import Counter


def _temporal_solver(minimum_duration, exact_coupons):
    def solve(data):
        required = data.get("required", [])
        full_mask = (1 << len(required)) - 1
        visit_masks = [0] * data["n"]
        for index, node in enumerate(required):
            visit_masks[node] |= 1 << index

        source = data["source"]
        initial_mask = visit_masks[source]
        start_state = (source, initial_mask, 0)
        distances = {start_state: data["start"]}
        queue = [(data["start"],) + start_state]
        coupon_limit = data["coupons"]

        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distances.get(state) != arrival:
                continue
            coupons_ok = used == coupon_limit if exact_coupons else used <= coupon_limit
            if node == data["target"] and mask == full_mask and coupons_ok:
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupon_limit:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                next_node = edge["v"]
                next_mask = mask | visit_masks[next_node]
                for duration, next_used in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, next_used)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time,) + next_state)
        return {"arrival": None}

    return solve


def _component_06(data):
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), data["rounding"])
        tax = rounded(net * event.get("tax_bp", 0), data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


