import heapq
from itertools import product, combinations


def _route(data, exact, minimum):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source, start = data["source"], data["start"]
    initial_mask = bits.get(source, 0)
    initial = (source, initial_mask, 0)
    best = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    coupons = data["coupons"]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != time:
            continue
        if (node == data["target"] and mask == full and
                (used == coupons if exact else used <= coupons)):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                options.append((max(minimum, edge["duration"] - edge.get("discount", 0)), used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bits.get(nxt, 0)
                next_state = (nxt, next_mask, next_used)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, next_used))
    return {"arrival": None}


def _build_route(exact, minimum):
    return lambda data: _route(data, exact, minimum)


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        eid = event.get("id", "anonymous:" + str(pos))
        key = (seq, event.get("revision", 0), pos)
        if eid not in winners or key > winners[eid][0]:
            winners[eid] = (key, event)

    def rounded(num, den):
        if data["rounding"] == "half_up":
            return (num + den // 2) // den
        return num // den

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        vals = [-1] + sorted(row["version"] for row in packages[name])
        choices.append(vals)
    best_vector = None
    best_result = None
    for vector in product(*choices):
        selected = dict(zip(names, vector))
        if any(selected[n] < lo or selected[n] > hi for n, (lo, hi) in roots.items()
               if selected[n] != -1):
            # Handle missing roots and range checks below.
            pass
        if any(selected.get(n, -1) == -1 or not lo <= selected[n] <= hi
               for n, (lo, hi) in roots.items()):
            continue
        valid = True
        rows = {}
        for name, version in selected.items():
            if version == -1:
                continue
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                valid = False
                break
            rows[name] = next(row for row in packages[name] if row["version"] == version)
        if not valid:
            continue
        edges = {name: [] for name in rows}
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feat = dep.get("feature", "")
                if feat and feat not in features:
                    continue
                other = dep["name"]
                version = selected.get(other, -1)
                if version == -1 or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
            if not valid:
                break
        if not valid:
            continue
        visiting, done = set(), set()
        def visit(name):
            if name in visiting:
                return False
            if name in done:
                return True
            visiting.add(name)
            if any(not visit(dep) for dep in edges[name]):
                return False
            visiting.remove(name)
            done.add(name)
            return True
        if not all(visit(name) for name in edges):
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_result = {n: v for n, v in selected.items() if v != -1}
    if best_result is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_result}


