def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    options = []
    for name in names:
        versions = [None] + sorted(row["version"] for row in packages[name])
        options.append(versions)

    best_key = None
    best = None
    for values in product(*options):
        selected = {name: version for name, version in zip(names, values) if version is not None}
        rows = {name: next(row for row in packages[name] if row["version"] == version)
                for name, version in selected.items()}
        valid = True
        for name, (low, high) in roots.items():
            if name not in selected or not low <= selected[name] <= high:
                valid = False
                break
        if not valid:
            continue
        for name, version in selected.items():
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                valid = False
                break
        if not valid:
            continue

        graph = {name: [] for name in selected}
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if other not in selected or not dep["min"] <= selected[other] <= dep["max"]:
                    valid = False
                    break
                graph[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in selected:
                valid = False
                break
            reachable.add(name)
            stack.extend(graph[name])
        if not valid or reachable != set(selected):
            continue

        active, finished = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(acyclic(name) for name in graph):
            continue

        key = tuple(selected.get(name, -1) for name in names)
        if best_key is None or key < best_key:
            best_key, best = key, selected
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
