def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best = None

    def acyclic(graph):
        done, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(child) for child in graph.get(name, ())):
                return False
            active.remove(name)
            done.add(name)
            return True
        return all(visit(name) for name in graph)

    def search(pending, chosen, graph):
        nonlocal best, best_vector
        if not pending:
            if not acyclic(graph):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector, best = vector, dict(chosen)
            return
        name, low, high, parent = pending[0]
        rest = pending[1:]
        next_graph = {key: set(value) for key, value in graph.items()}
        next_graph.setdefault(name, set())
        if parent is not None:
            next_graph.setdefault(parent, set()).add(name)

        if name in chosen:
            version = chosen[name]
            if low <= version <= high:
                search(rest, chosen, next_graph)
            return

        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            updated = dict(chosen)
            updated[name] = version
            extra = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if not feature or feature in features:
                    extra.append((dep["name"], dep["min"], dep["max"], name))
            search(rest + extra, updated, next_graph)

    pending = [(name, bounds[0], bounds[1], None)
               for name, bounds in data["roots"].items()]
    search(pending, {}, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _quota(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in subset:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        # End events sort before starts at the same time (half-open intervals).
        active = 0
        feasible = True
        for _, change in sorted(events, key=lambda item: (item[0], item[1])):
            active += change
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue
        value = sum(job["value"] for job in subset)
        selected = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and selected > best_ids)):
            best_value, best_ids = value, selected

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


