from itertools import product
import heapq
from collections import Counter


def _ledger(priority, tax_base):
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            if priority == "sequence":
                rank = (seq, event.get("revision", 0), pos)
            else:
                rank = (event.get("revision", 0), pos)
            if event_id not in chosen or rank > chosen[event_id][0]:
                chosen[event_id] = (rank, event)

        mode = data["rounding"]

        def rounded(n, d=10000):
            return (n + d // 2) // d if mode == "half_up" else n // d

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            base = net if tax_base == "discounted" else raw
            total = net + rounded(base * event.get("tax_bp", 0))
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data.get("roots", {})
    choices = []
    for name in names:
        allowed = [row["version"] for row in packages[name]
                   if row["version"] not in blocked.get(name, [])
                   and (name not in pins or row["version"] == pins[name])]
        choices.append([-1] + allowed)

    best = None
    best_vector = None
    for vector in product(*choices):
        selected = {name: version for name, version in zip(names, vector)
                    if version != -1}
        if any(name not in selected or not low <= selected[name] <= high
               for name, (low, high) in roots.items()):
            continue
        rows = {name: next(row for row in packages[name]
                           if row["version"] == version)
                for name, version in selected.items()}
        edges = {}
        valid = True
        for name, row in rows.items():
            deps = [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in deps:
                target = dep["name"]
                version = selected.get(target, -1)
                if version == -1 or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            if name in edges:
                stack.extend(edges[name])
        if reachable != set(selected):
            continue

        done, active = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            done.add(name)
            return True
        if not all(acyclic(name) for name in selected):
            continue

        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = selected
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    usable = [job for job in jobs if job["id"] not in blocked]
    best_ids = None
    best_value = None
    for mask in range(1 << len(usable)):
        if mask.bit_count() != k:
            continue
        selected = [job for i, job in enumerate(usable) if mask >> i & 1]
        ids = tuple(sorted(job["id"] for job in selected))
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in selected)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active = []
        compatible = True
        for job in sorted(selected, key=lambda row: (row["start"], row["end"], row["id"])):
            while active and active[0] <= job["start"]:
                heapq.heappop(active)
            heapq.heappush(active, job["end"])
            if len(active) > 2:
                compatible = False
                break
        if not compatible:
            continue
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    start_mask = bit.get(start_node, 0)
    start_time = data["start"]
    initial = (start_node, data["coupons"], start_mask)
    distances = {initial: start_time}
    queue = [(start_time, start_node, data["coupons"], start_mask)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, remaining, mask = heapq.heappop(queue)
        state = (node, remaining, mask)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            next_mask = mask | bit.get(edge["v"], 0)
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], left, next_mask)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], left, next_mask))
    return {"arrival": None}


